function shelfBands(arr) {
  if (arr.length === 0) return [];
  let result = [];
  let current = arr[0];
  let sum = 0;
  for (let num of arr) {
    if (Math.sign(num) === Math.sign(current)) {
      sum += num;
    } else {
      result.push(sum);
      current = num;
      sum = num;
    }
  }
  result.push(sum);
  return result;
}
