function stampShift(dateStr, offset) {
  const [y, m, d] = dateStr.split('-').map(Number);
  let totalMinutes = (y - 1) * 360 * 24 * 60 + (m - 1) * 30 * 24 * 60 + (d - 1) * 24 * 60 + offset;
  const year = 1 + Math.floor(totalMinutes / (360 * 24 * 60));
  totalMinutes %= 360 * 24 * 60;
  const month = 1 + Math.floor(totalMinutes / (30 * 24 * 60));
  totalMinutes %= 30 * 24 * 60;
  const day = 1 + Math.floor(totalMinutes / (24 * 60));
  totalMinutes %= 24 * 60;
  const hour = Math.floor(totalMinutes / 60);
  const minute = totalMinutes % 60;
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')} ${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}
